      updatePriceDisplay();

      // ========================================
      // Comparison Table Toggle
      // ========================================
      const comparisonToggleBtn = document.getElementById('comparisonToggleBtn');
      const comparisonTableWrapper = document.getElementById('comparisonTableWrapper');
      const comparisonToggleText = document.getElementById('comparisonToggleText');
      const comparisonToggleIcon = document.getElementById('comparisonToggleIcon');

      comparisonToggleBtn.addEventListener('click', function () {
        const isExpanded = comparisonTableWrapper.classList.toggle('expanded');
        comparisonToggleText.textContent = isExpanded ? 'Hide features' : 'See all features';
        comparisonToggleIcon.style.transform = isExpanded ? 'rotate(180deg)' : 'rotate(0deg)';
      });

      // ========================================
      // FAQ Accordion
      // ========================================
      const faqItems = document.querySelectorAll('.faq-item');

      faqItems.forEach(function (item) {
        const question = item.querySelector('.faq-question');
        const answer = item.querySelector('.faq-answer');
        const chevron = item.querySelector('.faq-chevron');

        question.addEventListener('click', function () {
          const isOpen = answer.classList.contains('open');

          // Close all other FAQ items first (accordion behavior)
          faqItems.forEach(function (otherItem) {
            otherItem.querySelector('.faq-answer').classList.remove('open');
            otherItem.querySelector('.faq-chevron').classList.remove('open');
            otherItem.querySelector('.faq-question').setAttribute('aria-expanded', 'false');
          });

          // Toggle the clicked item (if it was closed, open it)
          if (!isOpen) {
            answer.classList.add('open');
            chevron.classList.add('open');
            question.setAttribute('aria-expanded', 'true');
          }
        });
      });

    })();
