let isAnnual = false;

const prices = {
  business:   { monthly: 18, annual: 15 },
  businessAi: { monthly: 24, annual: 20 }
};

function getTeamSize() {
  return parseInt(teamSlider.value, 10);
}

function getCurrentPrice(plan) {
  return isAnnual ? prices[plan].annual : prices[plan].monthly;
}

function updatePriceDisplay() {
  const teamSize = getTeamSize();
  const businessPrice = getCurrentPrice('business');
  const businessAiPrice = getCurrentPrice('businessAi');

  businessPriceEl.textContent = '$' + businessPrice;
  businessAiPriceEl.textContent = '$' + businessAiPrice;

  const businessTotal = businessPrice * teamSize;
  const businessAiTotal = businessAiPrice * teamSize;

  businessTotalEl.textContent = '$' + businessTotal.toLocaleString() + '/mo for ' + teamSize + ' member' + (teamSize === 1 ? '' : 's');
  businessAiTotalEl.textContent = '$' + businessAiTotal.toLocaleString() + '/mo for ' + teamSize + ' member' + (teamSize === 1 ? '' : 's');
}

